import { describe, expect, it } from "vitest";
import type { LlmCallRecord } from "../types";
import { deriveLlmCallView } from "./deriveLlmCallView";

function makeRecord(overrides: Partial<LlmCallRecord>): LlmCallRecord {
  return {
    id: "r1",
    timestamp: 100,
    purpose: null,
    request_model: "gpt-4o",
    response_model: "gpt-4o-2024-08-06",
    input_tokens: 120,
    output_tokens: 8,
    latency_ms: 1250,
    time_to_first_token_ms: null,
    tool_names: ["lock_card", "set_fields"],
    gated_tool_names: ["submit_travel_notice"],
    response_tool_names: ["lock_card"],
    prompt_messages: [{ role: "user", content: "lock my card" }],
    response_messages: [
      {
        role: "assistant",
        content: "On it.",
        tool_calls: [{ id: "c1", name: "lock_card", arguments: {} }],
      },
    ],
    is_error: false,
    error_message: null,
    ...overrides,
  };
}

describe("deriveLlmCallView", () => {
  it("derives labels, tool lists and messages", () => {
    const view = deriveLlmCallView(makeRecord({}));
    expect(view.model).toBe("gpt-4o-2024-08-06");
    expect(view.durationLabel).toBe("1.3 s");
    expect(view.tokensLabel).toBe("120 → 8 tokens");
    expect(view.toolNames).toEqual(["lock_card", "set_fields"]);
    expect(view.gatedToolNames).toEqual(["submit_travel_notice"]);
    expect(view.promptMessages).toEqual([{ role: "user", content: "lock my card" }]);
    expect(view.responseMessages).toEqual([{ role: "assistant", content: "On it.\n→ lock_card" }]);
  });

  it("falls back to the request model and hides absent labels", () => {
    const view = deriveLlmCallView(
      makeRecord({
        response_model: null,
        latency_ms: 250,
        input_tokens: null,
        output_tokens: null,
        prompt_messages: null,
        response_messages: null,
      }),
    );
    expect(view.model).toBe("gpt-4o");
    expect(view.durationLabel).toBe("250 ms");
    expect(view.tokensLabel).toBeNull();
    expect(view.promptMessages).toEqual([]);
    expect(view.responseMessages).toEqual([]);
  });

  it("derives tool-call-only response messages as the arrow line", () => {
    const view = deriveLlmCallView(
      makeRecord({
        response_messages: [
          {
            role: "assistant",
            tool_calls: [
              { id: "c1", name: "lock_card", arguments: {} },
              { id: "c2", name: "set_fields", arguments: {} },
            ],
          },
        ],
      }),
    );
    expect(view.responseMessages).toEqual([
      { role: "assistant", content: "→ lock_card, set_fields" },
    ]);
  });

  it("shows a placeholder for the missing side of the token pair", () => {
    const view = deriveLlmCallView(makeRecord({ input_tokens: 120, output_tokens: null }));
    expect(view.tokensLabel).toBe("120 → ? tokens");
  });

  it("carries error state", () => {
    const view = deriveLlmCallView(
      makeRecord({ is_error: true, error_message: "rate limited", response_model: null }),
    );
    expect(view.isError).toBe(true);
    expect(view.errorMessage).toBe("rate limited");
  });
});
